import{_ as a,o as t,c as n,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"13. LLM 推理与部署: KV Cache / PagedAttention / 连续批处理 / 量化","description":"","frontmatter":{},"headers":[],"relativePath":"ai-ml/llm-inference.md","filePath":"ai-ml/llm-inference.md","lastUpdated":1788475713000}'),l={name:"ai-ml/llm-inference.md"};function p(i,s,o,r,c,m){return t(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="_13-llm-推理与部署-kv-cache-pagedattention-连续批处理-量化" tabindex="-1">13. LLM 推理与部署: KV Cache / PagedAttention / 连续批处理 / 量化 <a class="header-anchor" href="#_13-llm-推理与部署-kv-cache-pagedattention-连续批处理-量化" aria-label="Permalink to &quot;13. LLM 推理与部署: KV Cache / PagedAttention / 连续批处理 / 量化&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>训练决定了模型&quot;会什么&quot;，推理决定了模型&quot;多贵、多快、能服务多少人&quot;。LLM 推理的物理瓶颈不是算力而是<strong>显存带宽</strong>：decode 阶段每生成 1 个 token 都要把全部权重读一遍，且 <strong>KV cache</strong>（历史的 key/value 缓存）随序列长度线性增长、按请求动态分配——这两点催生了 vLLM 的 <strong>PagedAttention</strong>（按物理块分配显存，消除碎片）和<strong>连续批处理</strong>（新请求动态插入解码中的请求）。再叠加<strong>投机解码</strong>（小模型草稿 + 大模型验证）和<strong>量化</strong>（GPTQ/AWQ，权重压到 4bit）后，一个 70B 模型才能在单卡上跑出可用的吞吐。这一章给全链路的数字账本和工程架构。</p><p>读完应能：</p><ol><li>推导 decode 的 token 速度公式（≈ 显存带宽 / 模型字节数），并解释为什么小模型不一定比大模型便宜。</li><li>写出 KV cache 的显存公式（2 × layers × kv_heads × head_dim × seq_len × bytes），说出 GQA/MQA 解决什么。</li><li>讲清 PagedAttention 的物理块/逻辑块映射与连续批处理的收益（显存利用率、调度自由度）。</li><li>解释投机解码为什么&quot;多算一次小模型反而更快&quot;，以及量化 W4A16 的误差来源与校准（GPTQ/AWQ）。</li><li>画出生产 serving 架构：prefill/decode 分离、GPU 池、路由、弹性扩容、容灾。</li></ol><hr><h2 id="一、先算账-decode-为什么慢" tabindex="-1">一、先算账: decode 为什么慢 <a class="header-anchor" href="#一、先算账-decode-为什么慢" aria-label="Permalink to &quot;一、先算账: decode 为什么慢&quot;">​</a></h2><p>LLM 推理分两个阶段：</p><ul><li><strong>prefill</strong>：一次处理整个 prompt，并行度高，受<strong>计算</strong>（FLOPs）限制；</li><li><strong>decode</strong>：逐 token 生成，每次只算 1 个 token，受<strong>显存带宽</strong>限制。</li></ul><p>decode 每步的耗时 ≈ <strong>读一遍全部权重的时间</strong>：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>tokens/s</mtext><mo>≈</mo><mfrac><mrow><mi>B</mi><msub><mi>W</mi><mtext>HBM</mtext></msub></mrow><mtext>模型字节数</mtext></mfrac></mrow><annotation encoding="application/x-tex">\\text{tokens/s} \\approx \\frac{BW_{\\text{HBM}}}{\\text{模型字节数}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">tokens/s</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">模型字节数</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">HBM</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>以 70B fp16 模型（140 GB）、H100（3.35 TB/s）为例：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3350</mn><mi mathvariant="normal">/</mi><mn>140</mn><mo>≈</mo><mn>24</mn></mrow><annotation encoding="application/x-tex">3350/140 \\approx 24</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">3350/140</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">24</span></span></span></span> tokens/s——这是<strong>单请求理论上限</strong>，实际 10-15 tokens/s 就很好了。</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>反直觉结论：<strong>模型小一倍 ≠ 快一倍</strong>。7B 和 70B 都吃同样的&quot;每 token 读全部权重&quot;，7B 只是少几倍字节（且更吃不到带宽饱和）。真正让吞吐起飞的是<strong>同时服务多个请求共享权重读</strong>——批处理是唯一免费午餐。</p></div><h2 id="二、kv-cache-推理显存的头号消耗" tabindex="-1">二、KV cache: 推理显存的头号消耗 <a class="header-anchor" href="#二、kv-cache-推理显存的头号消耗" aria-label="Permalink to &quot;二、KV cache: 推理显存的头号消耗&quot;">​</a></h2><p>自注意力里，每个历史 token 的 K/V 都要留给后续 token 查询：</p><p class="katex-block"><span class="katex-error" title="ParseError: KaTeX parse error: Expected &#39;EOF&#39;, got &#39;_&#39; at position 69: …\\times \\text{kv_̲heads} \\times \\…" style="color:#cc0000;">\\text{KV bytes} = 2(\\text{K+V}) \\times \\text{layers} \\times \\text{kv_heads} \\times \\text{head_dim} \\times \\text{seq\\_len} \\times \\text{bytes} </span></p><p>70B（80 layers, GQA-8, head_dim 128, fp16）在 4K 上下文：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>2</mn><mo>×</mo><mn>80</mn><mo>×</mo><mn>8</mn><mo>×</mo><mn>128</mn><mo>×</mo><mn>4096</mn><mo>×</mo><mn>2</mn><mtext>B</mtext><mo>≈</mo><mn>1.34</mn><mtext> GB / 请求</mtext></mrow><annotation encoding="application/x-tex">2 \\times 80 \\times 8 \\times 128 \\times 4096 \\times 2 \\text{B} \\approx 1.34 \\text{ GB / 请求} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">80</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">8</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">4096</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">2</span><span class="mord text"><span class="mord">B</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1.34</span><span class="mord text"><span class="mord"> GB / </span><span class="mord cjk_fallback">请求</span></span></span></span></span></span></p><p>4096 并发请求就要 ~5.5 TB——<strong>超过单机显存</strong>。KV cache 是&quot;按请求动态分配、随生成长短不一&quot;的内存，和操作系统面临的内存碎片问题一模一样，于是有了 PagedAttention。</p><h3 id="gqa-mqa" tabindex="-1">GQA / MQA <a class="header-anchor" href="#gqa-mqa" aria-label="Permalink to &quot;GQA / MQA&quot;">​</a></h3><p>多头注意力每头一份 KV（MHA）太贵；<strong>MQA</strong>（所有头共享 1 份 KV）省显存但损质量；<strong>GQA</strong>（分若干组共享）是折中——Llama 2/3 70B 用 GQA-8，KV 直接除以 8。这是&quot;用质量换显存&quot;的教科书权衡。</p><h2 id="三、pagedattention-vllm" tabindex="-1">三、PagedAttention / vLLM <a class="header-anchor" href="#三、pagedattention-vllm" aria-label="Permalink to &quot;三、PagedAttention / vLLM&quot;">​</a></h2><h3 id="_3-1-问题" tabindex="-1">3.1 问题 <a class="header-anchor" href="#_3-1-问题" aria-label="Permalink to &quot;3.1 问题&quot;">​</a></h3><p>朴素实现：请求进来一次性分配 <code>max_seq_len</code> 的连续显存。结果：</p><ul><li><strong>内部碎片</strong>：每个请求只用到一小段；</li><li><strong>外部碎片</strong>：连续分配在并发请求间互相挤压；</li><li>显存利用率往往只有 20-40%。</li></ul><h3 id="_3-2-解法-按块分配" tabindex="-1">3.2 解法: 按块分配 <a class="header-anchor" href="#_3-2-解法-按块分配" aria-label="Permalink to &quot;3.2 解法: 按块分配&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>逻辑 KV cache (连续 token 序列)</span></span>
<span class="line"><span>  [t0 t1 t2 t3 | t4 t5 t6 t7 | t8 ...]</span></span>
<span class="line"><span>      ↓  逻辑块 → 物理块映射 (类似虚拟内存页表)</span></span>
<span class="line"><span>物理块 (固定大小, 如 16 tokens/block, 分散在显存各处)</span></span>
<span class="line"><span>  [block 7] [block 3] [block 9] ...</span></span></code></pre></div><ul><li>按需分配物理块，<strong>不需要预测最大长度</strong> → 内部碎片消除；</li><li>块可分散 → 外部碎片消除，且<strong>多请求可共享同一物理块</strong>（beam search/前缀缓存）；</li><li>代价：block table 一次间接寻址 + 块内 padding（最后一个块不满）。</li></ul><h3 id="_3-3-连续批处理-continuous-batching" tabindex="-1">3.3 连续批处理（Continuous Batching） <a class="header-anchor" href="#_3-3-连续批处理-continuous-batching" aria-label="Permalink to &quot;3.3 连续批处理（Continuous Batching）&quot;">​</a></h3><p>传统静态批处理：等整批全部生成完才回收。连续批处理让<strong>新请求随时插入</strong>解码中的批次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t=0: [A prefill] [B decode] [C decode]</span></span>
<span class="line"><span>t=1: [B decode] [C decode] [D prefill]   ← D 插队, A 已结束</span></span></code></pre></div><p>收益：吞吐量提升 2-10 倍（大模型多 10x），因为 decode 的带宽受限状态能一直满载。调度策略（FCFS、SJF、抢占）直接决定吞吐 vs 延迟的曲线——这又是 OS 调度问题的镜像。</p><h2 id="四、投机解码-多算一次反而更快" tabindex="-1">四、投机解码: 多算一次反而更快 <a class="header-anchor" href="#四、投机解码-多算一次反而更快" aria-label="Permalink to &quot;四、投机解码: 多算一次反而更快&quot;">​</a></h2><p>大模型逐 token 生成是串行的，但<strong>验证多个候选 token 可以并行</strong>：</p><ol><li>小模型（draft model）快速生成 k 个候选 token；</li><li>大模型一次 prefill 并行验证 k 个位置；</li><li>从首个不一致处截断，接受一致的前缀。</li></ol><p>加速比 ≈ 草稿接受率 × k（接受率高时接近 k 倍）。典型：70B + 小草稿可达 2-3x。变体：<strong>self-speculative</strong>（同模型浅层草稿）、<strong>Medusa</strong>（额外 head 并行预测）。限制：草稿模型要与大模型分布接近，且 k 太大时验证成本上升。</p><h2 id="五、量化推理-4bit-权重-16bit-激活" tabindex="-1">五、量化推理: 4bit 权重 + 16bit 激活 <a class="header-anchor" href="#五、量化推理-4bit-权重-16bit-激活" aria-label="Permalink to &quot;五、量化推理: 4bit 权重 + 16bit 激活&quot;">​</a></h2><p>decode 瓶颈是带宽，所以<strong>权重越小越快</strong>。W4A16（权重 4bit、激活 16bit）把 70B 从 140GB 压到 ~35GB——单卡 H100 直接能跑。</p><p>朴素 RTN（round-to-nearest）误差大，于是有：</p><table tabindex="0"><thead><tr><th>方法</th><th>核心思想</th><th>特点</th></tr></thead><tbody><tr><td><strong>GPTQ</strong></td><td>逐层逐列做<strong>二阶近似误差最小化</strong>（Hessian 逆），量化时补偿</td><td>一次性离线量化，精度好</td></tr><tr><td><strong>AWQ</strong></td><td>观察激活分布，<strong>按通道保护重要权重</strong>（缩放通道）</td><td>不重训，速度快，精度稳</td></tr><tr><td><strong>FP8 训练后量化</strong></td><td>直接 FP8，H100 原生支持</td><td>精度损失小，工业默认</td></tr><tr><td><strong>KV cache 量化（FP8/INT8）</strong></td><td>压 KV 而非权重</td><td>显存减半，长上下文必备</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>量化后一定要<strong>看下游任务精度而不是困惑度</strong>：4bit 对推理/代码任务往往无感，但对数学/长尾知识任务可能掉点。生产上线流程 = 离线校准 → 任务集评测 → A/B 灰度，缺一不可。</p></div><h2 id="六、生产-serving-架构" tabindex="-1">六、生产 serving 架构 <a class="header-anchor" href="#六、生产-serving-架构" aria-label="Permalink to &quot;六、生产 serving 架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 ─► API Gateway ─► 调度/路由 (按模型、按租户、按负载)</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ├─► Prefill 池 (算力密集, A100/H100)</span></span>
<span class="line"><span>              │       │  KVCache/激活经 RDMA/PCIe 传递</span></span>
<span class="line"><span>              ├─► Decode 池 (带宽密集, 长 KV cache)</span></span>
<span class="line"><span>              │       │  → vLLM/TensorRT-LLM/SGLang</span></span>
<span class="line"><span>              └─► 冷路径: 量化/蒸馏模型、请求排队、限流、回退</span></span></code></pre></div><p>关键设计点：</p><ul><li><strong>PD 分离（prefill/decode disaggregation）</strong>：prefill 吃算力、decode 吃带宽，混跑互相拖累；分离后各自最优批大小，但 KV 传输有成本；</li><li><strong>前缀缓存</strong>：系统提示词/文档前缀共享 KV 块（PagedAttention 的共享能力），长文档 RAG 场景吞吐翻倍；</li><li><strong>弹性与容灾</strong>：按 QPS 扩缩容、队列背压、超时降级（小模型兜底）、多副本灰度；</li><li><strong>观察指标</strong>：TTFT（首 token 延迟）、TPOT/ITL（token 间隔）、吞吐（tokens/s/GPU）、KV 命中率、队列深度。</li></ul><h2 id="七、一页速查" tabindex="-1">七、一页速查 <a class="header-anchor" href="#七、一页速查" aria-label="Permalink to &quot;七、一页速查&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>瓶颈:  prefill=算力, decode=带宽; tokens/s ≈ 带宽/权重字节</span></span>
<span class="line"><span>KV:    2×L×kv_heads×head_dim×seq×bytes; GQA/MQA 除以组数</span></span>
<span class="line"><span>PagedAttention: 逻辑块→物理块映射, 消除内外碎片, 支持共享</span></span>
<span class="line"><span>批处理: 连续批处理让新请求插队 → 吞吐 2-10x</span></span>
<span class="line"><span>加速:   投机解码(草稿+验证) 2-3x; 前缀缓存共享 KV</span></span>
<span class="line"><span>量化:   W4A16: GPTQ/AWQ/FP8; KV 量化撑长上下文</span></span>
<span class="line"><span>架构:   PD 分离 + GPU 池 + 路由/限流 + 弹性; 盯 TTFT/TPOT/吞吐</span></span></code></pre></div><p>下一篇: <a href="./../_meta/">元抽象卷 · 跨章节大主题</a>。</p>`,48)])])}const g=a(l,[["render",p]]);export{h as __pageData,g as default};
